.card {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
  margin: 10px;
}

.nav .link { color: green; }
#menu a    { color: red; }
a.link     { color: blue; }

function Profile({ id }) {
  const [user, setUser] = useState(null);
  useEffect(() => {
    fetch(`/api/users/${id}`)
      .then((r) => r.json())
      .then(setUser);
  });
  return <p>{user?.name}</p>;
}

const [count, setCount] = useState(0);

function handleClick() {
  setCount(count + 1);
  setCount(count + 1);
}
